<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { EditorState } from '@codemirror/state';
  import { EditorView, keymap, lineNumbers, drawSelection, highlightActiveLine, highlightActiveLineGutter } from '@codemirror/view';
  import { defaultKeymap, history, historyKeymap, indentWithTab, undo, redo, undoDepth, redoDepth } from '@codemirror/commands';
  import { syntaxHighlighting, defaultHighlightStyle } from '@codemirror/language';
  import { lintGutter, setDiagnostics, type Diagnostic as CMDiagnostic } from '@codemirror/lint';
  import { Window, Dialogs, Clipboard, Events } from '@wailsio/runtime';
  import { exbasicLanguage } from './lib/exbasic';
  import { StudioService as studio } from '../bindings/exbasicstudio/internal/studio';

  type ATRConfig = {enabled:boolean;tool:string;filesystem:'sparta'|'eos';output:string;boot:boolean;exactSize:boolean;minimumSize:number;bootPage:number;files:string[]};
  type ProjectConfig = { name:string;entry:string;target:string;output:string;compiler:string;emulator:string;native:string;debug:boolean;includePaths:string[];assembly:string[];atr:ATRConfig };
  type ProjectFile = {path:string;size:number};
  type ProjectView = {root:string;config:ProjectConfig;files:ProjectFile[];directories:string[];kind:'local'|'ssh';remoteHost?:string;remotePath?:string};
  type ProjectTreeEntry = {path:string;name:string;depth:number;directory:boolean;size:number};
  type GitChange = {path:string;index:string;worktree:string};
  type GitStatus = {available:boolean;branch:string;summary:string;changes:GitChange[]};
  type Hit = {file:string;title:string;snippet:string};
  type Extension = {id:string;name:string;version:string;status:string};
  type Env = {workingDir:string;claudeAvailable:boolean;claudeVersion:string;compilerHint:string;emulatorHint:string;sshAvailable:boolean};
  type SSHHost = {alias:string;configFile:string};
  type SSHConfig = {alias:string;hostName:string;user:string;port:number;configFile:string;identityFiles:string[];proxyJump:string;strictHostKeyChecking:string};
  type BuildResult = {success:boolean;command:string;output:string;artifact:string;diskImage?:string;durationMs:number};
  type SearchResult = {path:string;line:number;text:string};
  type TerminalResult = {output:string;exitCode:number;workingDir:string};
  type ATREntry = {path:string;name:string;size:number;directory:boolean;attributes:number;boot:boolean;modified:string};
  type ATRView = {path:string;filesystem:'sparta'|'eos';sectorSize:number;sectors:number;bytes:number;freeBytes:number;entries:ATREntry[]};
  type EmulatorFrame = {running:boolean;image?:string;number?:number;hostDevice:boolean;hostDeviceName?:string;workspaceChanged?:boolean;error?:string};
  type EmulatorDrive = {image:string;enabled:boolean;readOnly:boolean};
  type EmulatorRDevice = {mode:'disabled'|'850'|'rverter';listenPort:number;connectBaud:300|1200|2400|4800|9600|19200;serialPort:string;modem:boolean};
  type EmulatorIDE = {enabled:boolean;image:string;compactFlash:boolean};
  type EmulatorProfile = {id:string;name:string;machine:'atari'|'xl'|'xe'|'5200';memory:'64'|'128'|'256'|'320-rambo'|'320-compy'|'1088';video:'ntsc'|'pal';cpuSpeed:100|150|200|300|500;basic:boolean;sioPatch:boolean;eos:boolean;ultimate1MB:boolean;scale:number;media:string;drives:EmulatorDrive[];rDevice:EmulatorRDevice;ide:EmulatorIDE;arguments:string[]};
  type EmulatorState = {running:boolean;profileId:string;artifact:string;hostDeviceName?:string};
  type BasicDiagnostic = {path:string;line:number;column:number;severity:'error'|'warning'|'info';message:string};
  type OpenTab = {path:string;content:string;dirty:boolean};
  type ChatMessage = {role:'user'|'assistant';text:string};
  type Activity = 'explorer'|'atr'|'search'|'source'|'run'|'emulator'|'extensions'|'manual'|'settings';
  type PanelTab = 'problems'|'output'|'terminal';
  type PaletteMode = 'commands'|'files';
  type CommandID = 'palette'|'quickOpen'|'file.open'|'file.new'|'file.newFolder'|'file.rename'|'file.delete'|'file.save'|'file.saveAll'|'editor.close'|'editor.undo'|'editor.redo'|'editor.split'|'editor.copyPath'|'editor.selectAll'|'nav.back'|'nav.forward'|'view.explorer'|'view.atr'|'view.search'|'view.source'|'view.panel'|'view.claude'|'build'|'run'|'emulator.open'|'emulator.start'|'emulator.restart'|'emulator.stop'|'terminal.focus'|'terminal.clear'|'manual'|'settings';
  type Command = {id:CommandID;label:string;shortcut?:string;icon?:string};
  type MenuItem = {label:string;action:CommandID;shortcut?:string};

  let editorHost:HTMLDivElement, splitHost:HTMLDivElement, paletteInput:HTMLInputElement, terminalInput:HTMLInputElement, newFileInput:HTMLInputElement, newFolderInput:HTMLInputElement;
  let editor:EditorView|undefined, splitEditor:EditorView|undefined, suppressEditorChange=false;
  let project:ProjectView|null=null, draft:ProjectConfig|null=null, env:Env|null=null;
  let tabs:OpenTab[]=[], activeFile='', welcomeOpen=true, dirty=false, busy=false, status='Ready';
  let output='Welcome to exBASIC Studio. Open a folder or create a project to begin.', problems:string[]=[];
  let primaryOpen=true, secondaryOpen=true, panelOpen=true, activity:Activity='explorer', panelTab:PanelTab='terminal';
  let projectPath='', projectName='helloatari', newFilePath='', newFolderPath='', selectedPath='', git:GitStatus|null=null, commitMessage='', diff='', diffPath='';
  let searchQuery='', searchResults:SearchResult[]=[], prompt='', chat:ChatMessage[]=[];
  let manualSearch='', hits:Hit[]=[], chapters:string[]=[], chapterText='', chosenChapter='', extensions:Extension[]=[], extensionQuery='';
  let terminalCommand='', terminalLog='exBASIC Studio integrated terminal\nType a command and press Enter.\n', terminalCwd='', terminalHistory:string[]=[], terminalHistoryIndex=0;
  let paletteOpen=false, paletteMode:PaletteMode='commands', paletteQuery='', menuOpen='', editorActionsOpen=false, pendingChord='', chordTimer=0;
  let navigation:string[]=[], navigationIndex=-1, navigating=false, panelMaximized=false, splitOpen=false;
  let cursorLine=1, cursorColumn=1, claudeMode:'plan'|'edit'|'auto'='plan', includeSelection=true;
  let collapsedFolders=new Set<string>();
  let atr:ATRView|null=null, atrPath='', atrSelected='', atrNewFolder='', atrCollapsed=new Set<string>();
  let remoteDialog=false, sshHost='', sshPath='.', sshConfigFile='', sshHosts:SSHHost[]=[], resolvedSSH:SSHConfig|null=null;
  let emulatorOpen=false, emulatorRunning=false, emulatorImage='', emulatorFrame=0, emulatorHostDevice=false, emulatorHostDeviceName='', emulatorTimer=0, emulatorPolling=false, emulatorConfigOpen=false, lintTimer=0;
  let emulatorProfiles:EmulatorProfile[]=[], emulatorProfileId='', emulatorDraft:EmulatorProfile|null=null, emulatorArgs='';

  const activities:{id:Activity;icon:string;label:string}[]=[
    {id:'explorer',icon:'files',label:'Explorer'},{id:'search',icon:'search',label:'Search'},
    {id:'atr',icon:'database',label:'ATR Explorer'},
    {id:'source',icon:'source-control',label:'Source Control'},{id:'run',icon:'debug-alt',label:'Run and Debug'},
    {id:'emulator',icon:'device-desktop',label:'Atari800 Emulator'},
    {id:'extensions',icon:'extensions',label:'Extensions'},{id:'manual',icon:'book',label:'exBASIC Manual'}
  ];
  const welcomeContent="' Welcome to exBASIC Studio\n' Open a folder from the Explorer to begin.\n";

  onMount(()=>{
    editor=new EditorView({parent:editorHost,state:EditorState.create({
      doc:welcomeContent,
      extensions:[lineNumbers(),drawSelection(),highlightActiveLine(),highlightActiveLineGutter(),history(),lintGutter(),
        keymap.of([...defaultKeymap,...historyKeymap,indentWithTab]),exbasicLanguage,syntaxHighlighting(defaultHighlightStyle),EditorView.lineWrapping,
        EditorView.updateListener.of(update=>{const head=update.state.selection.main.head;const line=update.state.doc.lineAt(head);cursorLine=line.number;cursorColumn=head-line.from+1;if(update.docChanged&&splitEditor){splitEditor.dispatch({changes:{from:0,to:splitEditor.state.doc.length,insert:update.state.doc.toString()}})}if(!update.docChanged||suppressEditorChange||!activeFile||activeFile==='@atari800')return;dirty=true;tabs=tabs.map(tab=>tab.path===activeFile?{...tab,content:update.state.doc.toString(),dirty:true}:tab);scheduleLint()}),
        EditorView.theme({'&':{height:'100%',fontSize:'13px',backgroundColor:'#1e1e1e',color:'#d4d4d4'},'.cm-content':{fontFamily:'Consolas, "Cascadia Code", monospace',padding:'9px 0',caretColor:'#aeafad'},'.cm-gutters':{backgroundColor:'#1e1e1e',color:'#858585',border:'none'},'.cm-activeLine':{backgroundColor:'#2a2d2e55'},'.cm-activeLineGutter':{backgroundColor:'#2a2d2e',color:'#c6c6c6'},'.cm-cursor':{borderLeftColor:'#aeafad'},'.cm-selectionBackground':{background:'#264f78 !important'},'.cm-scroller':{overflow:'auto'},'.cm-keyword':{color:'#569cd6'},'.cm-comment':{color:'#6a9955'},'.cm-number':{color:'#b5cea8'},'.cm-string':{color:'#ce9178'}})
      ]})});
    const stopDrops=Events.On('files-dropped',(event:any)=>{const data=event.data??event;const id=data?.details?.id??'';const paths=(data.files??[]) as string[];if(id.startsWith('atr-drop-')&&atr){const encoded=id.slice('atr-drop-'.length);const destination=encoded==='root'?'':decodeURIComponent(encoded);void importATRHostPaths(paths,destination);return}if(id.startsWith('project-drop-')&&project?.kind==='local'){const encoded=id.slice('project-drop-'.length);const destination=encoded==='root'?'':decodeURIComponent(encoded);void importProjectHostPaths(paths,destination)}});
    void(async()=>{try{env=await studio.GetEnvironment() as Env;projectPath=env.workingDir;chapters=(await studio.ManualFiles())??[];await loadEmulatorProfiles();const state=await studio.EmulatorStatus() as EmulatorState;emulatorRunning=state.running;if(state.profileId)selectEmulatorProfile(state.profileId)}catch(error){status='Unable to connect to the Go backend';output=String(error);panelTab='output';panelOpen=true}})();
    return()=>{stopDrops();window.clearTimeout(emulatorTimer);window.clearTimeout(lintTimer);window.clearTimeout(chordTimer);editor?.destroy();splitEditor?.destroy()};
  });

  function editorText(){return editor?.state.doc.toString()??''}
  function activeEditorTab(){return activeFile&&activeFile!=='@atari800'?tabs.find(tab=>tab.path===activeFile)??null:null}
  function scheduleLint(){window.clearTimeout(lintTimer);lintTimer=window.setTimeout(runLint,450)}
  async function runLint(){if(!project||project.kind==='ssh'||!activeFile.endsWith('.bas')||!editor)return;const path=activeFile,content=editorText();try{const result=(await studio.Lint(path,content)??[]) as BasicDiagnostic[];if(path!==activeFile||content!==editorText())return;const diagnostics:CMDiagnostic[]=result.map(item=>{const line=editor!.state.doc.line(Math.max(1,Math.min(item.line,editor!.state.doc.lines)));const from=Math.min(line.to,Math.max(line.from,line.from+Math.max(0,item.column-1)));return{from,to:Math.min(line.to,from+1),severity:item.severity,message:item.message}});editor.dispatch(setDiagnostics(editor.state,diagnostics));problems=result.map(item=>`${path}:${item.line}:${item.column}: ${item.message}`)}catch(error){status=`Lint unavailable: ${String(error)}`}}
  function putText(value:string,isDirty=false){if(!editor)return;suppressEditorChange=true;editor.dispatch({changes:{from:0,to:editor.state.doc.length,insert:value}});if(splitEditor)splitEditor.dispatch({changes:{from:0,to:splitEditor.state.doc.length,insert:value}});suppressEditorChange=false;dirty=isDirty}
  function syncActiveTab(){if(activeFile)tabs=tabs.map(tab=>tab.path===activeFile?{...tab,content:editorText(),dirty}:tab)}
  function canReplaceWorkspace(){syncActiveTab();const unsaved=tabs.filter(tab=>tab.dirty).map(tab=>tab.path);return unsaved.length===0||window.confirm(`Discard unsaved changes in ${unsaved.join(', ')}?`)}
  async function runTask(label:string,task:()=>Promise<void>){if(busy)return;busy=true;status=label;try{await task();status=label+' complete'}catch(error){status=label+' failed';output=String(error);panelTab='output';panelOpen=true}finally{busy=false}}
  async function useProject(view:ProjectView){if(emulatorRunning)await stopEmulator();closeSplit();project=view;draft=structuredClone(view.config);if(view.kind!=='ssh')projectPath=view.root;terminalCwd=view.root;tabs=[];activeFile='';welcomeOpen=true;dirty=false;selectedPath='';chat=[];navigation=[];navigationIndex=-1;output=`Opened ${view.root}`;if(view.config.entry&&view.files.some(file=>file.path.toLowerCase()===view.config.entry.toLowerCase()))await openFile(view.config.entry);else putText(welcomeContent);await refreshGit()}
  async function createProject(){if(canReplaceWorkspace())await runTask('Creating project',async()=>useProject(await studio.CreateProject(projectPath,projectName) as ProjectView))}
  async function openProject(){if(canReplaceWorkspace())await runTask('Opening folder',async()=>useProject(await studio.OpenProject(projectPath) as ProjectView))}
  async function chooseProject(){const selected=await Dialogs.OpenFile({Title:'Open Folder',Directory:projectPath,CanChooseDirectories:true,CanChooseFiles:false,AllowsMultipleSelection:false});const path=Array.isArray(selected)?selected[0]:selected;if(path){projectPath=path;await openProject()}}
  async function showRemoteDialog(){remoteDialog=true;resolvedSSH=null;try{sshHosts=(await studio.SSHHosts(sshConfigFile)??[]) as SSHHost[]}catch(error){output=String(error)}await tick()}
  async function inspectRemote(){if(!sshHost.trim())return;await runTask('Resolving SSH configuration',async()=>{resolvedSSH=await studio.ResolveSSHConfig(sshHost,sshConfigFile) as SSHConfig})}
  async function connectRemote(){if(!sshHost.trim()||!sshPath.trim()||!canReplaceWorkspace())return;await runTask('Connecting over SSH',async()=>{const view=await studio.OpenRemoteProject(sshHost,sshPath,sshConfigFile) as ProjectView;remoteDialog=false;await useProject(view)})}
  function recordNavigation(path:string){if(navigating)return;if(navigation[navigationIndex]===path)return;navigation=navigation.slice(0,navigationIndex+1);navigation=[...navigation,path];navigationIndex=navigation.length-1}
  async function openFile(path:string){if(!project)return;if(path===activeFile){selectedPath=path;return}syncActiveTab();const existing=tabs.find(tab=>tab.path===path);if(existing){activeFile=path;selectedPath=path;putText(existing.content,existing.dirty);recordNavigation(path);scheduleLint();return}const content=await studio.ReadFile(path);tabs=[...tabs,{path,content,dirty:false}];activeFile=path;selectedPath=path;putText(content);recordNavigation(path);scheduleLint()}
  async function navigate(delta:number){const next=navigationIndex+delta;if(next<0||next>=navigation.length)return;const previous=navigationIndex;navigating=true;navigationIndex=next;try{await openFile(navigation[next])}catch(error){navigationIndex=previous;status='Navigation failed';output=String(error);panelTab='output';panelOpen=true}finally{navigating=false}}
  function switchTab(path:string){if(path===activeFile)return;if(activeFile==='@atari800')void releaseEmulatorKeys();syncActiveTab();const tab=tabs.find(item=>item.path===path);if(tab){activeFile=path;selectedPath=path;putText(tab.content,tab.dirty);recordNavigation(path)}}
  function closeTab(path:string,event?:MouseEvent){event?.stopPropagation();const tab=tabs.find(item=>item.path===path);if(tab?.dirty&&!window.confirm(`Discard unsaved changes in ${path}?`))return;const index=tabs.findIndex(item=>item.path===path);tabs=tabs.filter(item=>item.path!==path);if(activeFile===path){const next=tabs[Math.min(index,tabs.length-1)];activeFile=next?.path??'';selectedPath=next?.path??'';if(!next){welcomeOpen=false;closeSplit()}putText(next?.content??'',next?.dirty??false)}}
  async function saveFile(){const tab=activeEditorTab();if(!project||!tab||!editor)return;const path=tab.path,content=editorText();await runTask('Saving',async()=>{await studio.SaveFile(path,content);tabs=tabs.map(item=>item.path===path?{...item,content,dirty:false}:item);if(activeFile===path)dirty=false})}
  async function saveAll(){if(!project)return;syncActiveTab();for(const tab of tabs.filter(item=>item.dirty))await studio.SaveFile(tab.path,tab.content);tabs=tabs.map(tab=>({...tab,dirty:false}));dirty=false}
  async function makeFile(){if(!project||!newFilePath.trim())return;const created=newFilePath.trim().replaceAll('\\','/').replace(/^\.\//,'');await runTask('Creating file',async()=>{if(project?.files.some(file=>file.path.toLowerCase()===created.toLowerCase()))throw new Error(`${created} already exists`);await studio.SaveFile(created,"' New exBASIC source\n");project=await studio.GetProject() as ProjectView;newFilePath='';await openFile(created)})}
  async function makeFolder(){if(!project||!newFolderPath.trim())return;const created=newFolderPath.trim().replaceAll('\\','/').replace(/^\.\//,'');await runTask('Creating folder',async()=>{if(project?.directories.some(directory=>directory.toLowerCase()===created.toLowerCase()))throw new Error(`${created} already exists`);project=await studio.CreateFolder(created) as ProjectView;newFolderPath=''})}
  async function beginNewFile(){showActivity('explorer');newFolderPath='';newFilePath='src/new.bas';await tick();newFileInput?.focus();newFileInput?.select()}
  async function beginNewFolder(){showActivity('explorer');newFilePath='';newFolderPath='src/new-folder';await tick();newFolderInput?.focus();newFolderInput?.select()}
  function applyProjectRename(oldPath:string,newPath:string,view:ProjectView){const oldPrefix=oldPath+'/';project=view;tabs=tabs.map(tab=>tab.path===oldPath||tab.path.startsWith(oldPrefix)?{...tab,path:newPath+tab.path.slice(oldPath.length)}:tab);if(activeFile===oldPath||activeFile.startsWith(oldPrefix))activeFile=newPath+activeFile.slice(oldPath.length);selectedPath=newPath}
  async function renameSelected(){if(!project||!selectedPath)return;const next=window.prompt('Rename to',selectedPath);if(!next||next===selectedPath)return;const old=selectedPath;await runTask('Renaming',async()=>applyProjectRename(old,next,await studio.RenamePath(old,next) as ProjectView))}
  async function deleteSelected(){if(!project||!selectedPath||!window.confirm(`Delete ${selectedPath}? This cannot be undone.`))return;const target=selectedPath;await runTask('Deleting',async()=>{project=await studio.DeletePath(target) as ProjectView;tabs=tabs.filter(tab=>tab.path!==target&&!tab.path.startsWith(target+'/'));if(activeFile===target||activeFile.startsWith(target+'/')){const next=tabs[0];activeFile=next?.path??'';if(!next){welcomeOpen=false;closeSplit()}putText(next?.content??'',next?.dirty??false)}selectedPath='';await refreshGit()})}
  async function openATR(path:string){if(!path)return;await runTask('Opening ATR image',async()=>{atr=await studio.ATROpen(path) as ATRView;atrPath=atr.path;atrSelected='';atrCollapsed=new Set()})}
  async function chooseATR(){const selected=await Dialogs.OpenFile({Title:'Open ATR Disk Image',Directory:project?.kind==='local'?project.root:projectPath,CanChooseDirectories:false,CanChooseFiles:true,AllowsMultipleSelection:false,Filters:[{DisplayName:'Atari disk images',Pattern:'*.atr'}]});const path=Array.isArray(selected)?selected[0]:selected;if(path)await openATR(path)}
  async function openConfiguredATR(){await runTask('Opening project ATR',async()=>{atr=await studio.ATRConfigured() as ATRView;atrPath=atr.path;atrSelected='';atrCollapsed=new Set()})}
  async function refreshATR(){if(atrPath)atr=await studio.ATROpen(atrPath) as ATRView}
  function atrParent(path:string){const index=path.lastIndexOf('/');return index<0?'':path.slice(0,index)}
  function atrDestination(){const selected=atr?.entries.find(item=>item.path===atrSelected);return selected?.directory?selected.path:atrParent(atrSelected)}
  function visibleATREntries(){return(atr?.entries??[]).filter(entry=>{let parent=atrParent(entry.path);while(parent){if(atrCollapsed.has(parent))return false;parent=atrParent(parent)}return true})}
  function atrDepth(path:string){return path.split('/').length-1}
  function toggleATRFolder(path:string){const next=new Set(atrCollapsed);next.has(path)?next.delete(path):next.add(path);atrCollapsed=next}
  function formatBytes(value:number){if(value<1024)return`${value} B`;if(value<1024*1024)return`${(value/1024).toFixed(1)} KB`;return`${(value/1024/1024).toFixed(1)} MB`}
  async function importATRHostPaths(paths:string[],destination=atrDestination()){if(!atr||!paths.length)return;await runTask('Importing into ATR',async()=>{atr=await studio.ATRImportFiles(atr!.path,destination,paths) as ATRView;atrPath=atr.path})}
  async function chooseATRImports(){if(!atr)return;const selected=await Dialogs.OpenFile({Title:'Add Files or Folders to ATR',CanChooseDirectories:true,CanChooseFiles:true,AllowsMultipleSelection:true});if(selected.length)await importATRHostPaths(selected)}
  async function makeATRFolder(){if(!atr)return;const name=atrNewFolder.trim();if(!name)return;const destination=atrDestination();const path=destination?`${destination}/${name}`:name;await runTask('Creating ATR folder',async()=>{atr=await studio.ATRMkdir(atr!.path,path) as ATRView;atrSelected=path;atrNewFolder=''})}
  async function renameATRSelected(){if(!atr||!atrSelected)return;const next=window.prompt('Rename or move ATR entry to',atrSelected);if(!next||next===atrSelected)return;await runTask('Renaming ATR entry',async()=>{atr=await studio.ATRRename(atr!.path,atrSelected,next) as ATRView;atrSelected=next})}
  async function removeATRSelected(){if(!atr||!atrSelected||!window.confirm(`Delete ${atrSelected} from the ATR image?`))return;const target=atrSelected;await runTask('Deleting ATR entry',async()=>{atr=await studio.ATRRemove(atr!.path,target) as ATRView;atrSelected=''})}
  async function extractATRSelected(){if(!atr||!atrSelected)return;const directory=await Dialogs.OpenFile({Title:'Extract ATR Entry To Folder',CanChooseDirectories:true,CanChooseFiles:false,AllowsMultipleSelection:false});const target=Array.isArray(directory)?directory[0]:directory;if(target)await runTask('Extracting ATR entry',async()=>{await studio.ATRExtractToDirectory(atr!.path,atrSelected,target)})}
  function startProjectDrag(event:DragEvent,path:string){event.dataTransfer?.setData('application/x-exbasic-project-path',path);if(event.dataTransfer)event.dataTransfer.effectAllowed='copyMove'}
  function startATRDrag(event:DragEvent,path:string){event.dataTransfer?.setData('application/x-exbasic-atr-path',path);if(event.dataTransfer)event.dataTransfer.effectAllowed='copyMove'}
  function switchActivityDuringDrag(event:DragEvent,id:Activity){const types=Array.from(event.dataTransfer?.types??[]);if((id==='atr'&&types.includes('application/x-exbasic-project-path'))||(id==='explorer'&&types.includes('application/x-exbasic-atr-path'))){activity=id;primaryOpen=true}}
  async function dropOnATR(event:DragEvent,destination:string){event.preventDefault();event.stopPropagation();if(!atr)return;const projectEntry=event.dataTransfer?.getData('application/x-exbasic-project-path');if(projectEntry){await runTask('Copying project item into ATR',async()=>{atr=await studio.ATRImportProject(atr!.path,destination,[projectEntry]) as ATRView});return}const atrEntry=event.dataTransfer?.getData('application/x-exbasic-atr-path');if(atrEntry){const name=atrEntry.split('/').pop()??atrEntry;const next=destination?`${destination}/${name}`:name;if(next===atrEntry||next.startsWith(atrEntry+'/'))return;await runTask('Moving ATR entry',async()=>{atr=await studio.ATRRename(atr!.path,atrEntry,next) as ATRView;atrSelected=next})}}
  async function importProjectHostPaths(paths:string[],destination=''){if(!project||project.kind==='ssh'||!paths.length)return;await runTask('Importing into project',async()=>{project=await studio.ImportProjectPaths(destination||'.',paths) as ProjectView})}
  async function dropOnProject(event:DragEvent,destination:string){event.preventDefault();event.stopPropagation();if(!project)return;const source=event.dataTransfer?.getData('application/x-exbasic-project-path');if(source){const name=source.split('/').pop()??source;const next=destination?`${destination}/${name}`:name;if(next===source||next.startsWith(source+'/'))return;await runTask('Moving project item',async()=>applyProjectRename(source,next,await studio.RenamePath(source,next) as ProjectView));return}const entry=event.dataTransfer?.getData('application/x-exbasic-atr-path');if(!entry||!atr||project.kind==='ssh')return;await runTask('Copying ATR entry into project',async()=>{project=await studio.ATRExtractToProject(atr!.path,entry,destination||'.') as ProjectView})}
  async function copyActivePath(){const tab=activeEditorTab();if(project&&tab){const value=project.kind==='ssh'?`${project.remoteHost}:${project.remotePath}/${tab.path}`:`${project.root}/${tab.path}`.replaceAll('\\','/');await Clipboard.SetText(value);status='Copied path'}}
  async function compile(run:boolean){if(!project)return;await runTask(run?'Running':'Building',async()=>{await saveAll();const result:BuildResult=run?await studio.RunWithProfile(emulatorProfileId):await studio.Build();output=`> ${result.command}\n\n${result.output||'(no compiler output)'}\n\n${result.success?'Build succeeded':'Build failed'} in ${result.durationMs} ms\n${result.artifact?`Artifact: ${result.artifact}`:''}${result.diskImage?`\nATR image: ${result.diskImage}`:''}`;problems=result.success?[]:[result.output||'The compiler reported a build failure.'];panelTab=result.success?'output':'problems';panelOpen=true;project=await studio.GetProject() as ProjectView;if(run&&result.success){emulatorRunning=true;openEmulatorTab()}})}
