  function projectTree(){
    const directories=new Set<string>();
    const addDirectory=(path:string)=>{let current=path.replaceAll('\\','/').replace(/^\/+|\/+$/g,'');while(current){directories.add(current);const slash=current.lastIndexOf('/');current=slash<0?'':current.slice(0,slash)}};
    for(const directory of project?.directories??[])addDirectory(directory);
    for(const file of project?.files??[]){const slash=file.path.lastIndexOf('/');if(slash>=0)addDirectory(file.path.slice(0,slash))}
    const childDirectories=new Map<string,string[]>(),childFiles=new Map<string,ProjectFile[]>();
    for(const directory of directories){const slash=directory.lastIndexOf('/'),parent=slash<0?'':directory.slice(0,slash);childDirectories.set(parent,[...(childDirectories.get(parent)??[]),directory])}
    for(const file of project?.files??[]){const slash=file.path.lastIndexOf('/'),parent=slash<0?'':file.path.slice(0,slash);childFiles.set(parent,[...(childFiles.get(parent)??[]),file])}
    const entries:ProjectTreeEntry[]=[];
    const walk=(parent:string,depth:number)=>{
      for(const directory of (childDirectories.get(parent)??[]).sort((a,b)=>fileName(a).localeCompare(fileName(b)))){
        entries.push({path:directory,name:fileName(directory),depth,directory:true,size:0});
        if(!collapsedFolders.has(directory))walk(directory,depth+1);
      }
      for(const file of (childFiles.get(parent)??[]).sort((a,b)=>fileName(a.path).localeCompare(fileName(b.path))))entries.push({path:file.path,name:fileName(file.path),depth,directory:false,size:file.size});
    };
    walk('',0);
    return entries;
  }
  function toggleFolder(folder:string){const next=new Set(collapsedFolders);next.has(folder)?next.delete(folder):next.add(folder);collapsedFolders=next}
  function filteredExtensions(){const query=extensionQuery.trim().toLowerCase();return extensions.filter(ext=>!query||`${ext.name} ${ext.id} ${ext.version}`.toLowerCase().includes(query))}
