  function menuItems(menu:string):MenuItem[]{const menus:Record<string,MenuItem[]>={File:[{label:'New File…',action:'file.new',shortcut:'Ctrl+N'},{label:'New Folder…',action:'file.newFolder'},{label:'Open Folder…',action:'file.open',shortcut:'Ctrl+K Ctrl+O'},{label:'Save',action:'file.save',shortcut:'Ctrl+S'},{label:'Save All',action:'file.saveAll'},{label:'Close Editor',action:'editor.close',shortcut:'Ctrl+W'}],Edit:[{label:'Undo',action:'editor.undo',shortcut:'Ctrl+Z'},{label:'Redo',action:'editor.redo',shortcut:'Ctrl+Y'},{label:'Command Palette…',action:'palette',shortcut:'Ctrl+Shift+P'},{label:'Quick Open…',action:'quickOpen',shortcut:'Ctrl+P'}],Selection:[{label:'Select All',action:'editor.selectAll',shortcut:'Ctrl+A'}],View:[{label:'Explorer',action:'view.explorer'},{label:'ATR Explorer',action:'view.atr'},{label:'Search',action:'view.search'},{label:'Source Control',action:'view.source'},{label:'Toggle Editor Split',action:'editor.split'},{label:'Toggle Panel',action:'view.panel',shortcut:'Ctrl+J'},{label:'Toggle Claude Code',action:'view.claude'}],Go:[{label:'Back',action:'nav.back',shortcut:'Alt+Left'},{label:'Forward',action:'nav.forward',shortcut:'Alt+Right'},{label:'Quick Open…',action:'quickOpen',shortcut:'Ctrl+P'}],Run:[{label:'Run Without Debugging',action:'run',shortcut:'F5'},{label:'Build',action:'build',shortcut:'F6'},{label:'Open Atari800',action:'emulator.open'},{label:'Start Atari800',action:'emulator.start'},{label:'Restart Atari800',action:'emulator.restart'},{label:'Stop Atari800',action:'emulator.stop',shortcut:'Shift+F5'}],Terminal:[{label:'Focus Terminal',action:'terminal.focus',shortcut:'Ctrl+`'},{label:'Clear Terminal',action:'terminal.clear'}],Help:[{label:'exBASIC Manual',action:'manual'},{label:'Project Settings',action:'settings'}]};return menus[menu]??[]}
  function commandEnabled(id:CommandID){
    const textTab=activeEditorTab();
    switch(id){
      case'file.open':return!busy;
      case'file.new':case'file.newFolder':return!!project&&!busy;
      case'file.rename':case'file.delete':return!!project&&!!selectedPath&&!busy;
      case'file.save':return!!project&&!!textTab&&!busy;
      case'file.saveAll':return!!project&&tabs.some(tab=>tab.dirty)&&!busy;
      case'editor.close':return(!!activeFile||welcomeOpen)&&!busy;
      case'editor.undo':return!!textTab&&!!editor&&undoDepth(editor.state)>0;
      case'editor.redo':return!!textTab&&!!editor&&redoDepth(editor.state)>0;
      case'editor.split':case'editor.copyPath':case'editor.selectAll':return!!textTab;
      case'quickOpen':return!!project;
      case'nav.back':return navigationIndex>0;
      case'nav.forward':return navigationIndex>=0&&navigationIndex<navigation.length-1;
      case'build':case'run':return!!project&&!busy;
      case'emulator.start':return!emulatorRunning&&!busy;
      case'emulator.restart':case'emulator.stop':return emulatorRunning&&!busy;
      case'terminal.focus':return!!project;
      case'settings':return!!project;
      default:return true;
    }
  }
  async function executeCommand(id:CommandID){
    menuOpen='';paletteOpen=false;editorActionsOpen=false;
    if(!commandEnabled(id))return;
    switch(id){
      case'palette':await showPalette('commands');return;
      case'quickOpen':await showPalette('files');return;
      case'file.open':await chooseProject();return;
      case'file.new':await beginNewFile();return;
      case'file.newFolder':await beginNewFolder();return;
      case'file.rename':await renameSelected();return;
      case'file.delete':await deleteSelected();return;
      case'file.save':await saveFile();return;
      case'file.saveAll':await runTask('Saving all',saveAll);return;
      case'editor.close':await closeActiveEditor();return;
      case'editor.undo':if(editor){undo(editor);editor.focus()}return;
      case'editor.redo':if(editor){redo(editor);editor.focus()}return;
      case'editor.split':await toggleSplit();return;
      case'editor.copyPath':await copyActivePath();return;
      case'editor.selectAll':if(editor){editor.dispatch({selection:{anchor:0,head:editor.state.doc.length}});editor.focus()}return;
      case'nav.back':await navigate(-1);return;
      case'nav.forward':await navigate(1);return;
      case'view.explorer':showActivity('explorer');return;
      case'view.atr':showActivity('atr');return;
      case'view.search':showActivity('search');return;
      case'view.source':showActivity('source');return;
      case'view.panel':panelOpen=!panelOpen;return;
      case'view.claude':secondaryOpen=!secondaryOpen;return;
      case'build':await compile(false);return;
      case'run':await compile(true);return;
      case'emulator.open':openInteractiveEmulator();return;
      case'emulator.start':await startEmulator();return;
      case'emulator.restart':await restartEmulator();return;
      case'emulator.stop':await stopEmulator();return;
      case'terminal.focus':panelOpen=true;panelTab='terminal';await tick();terminalInput?.focus();return;
      case'terminal.clear':terminalLog='exBASIC Studio integrated terminal\n';return;
      case'manual':showActivity('manual');return;
      case'settings':showActivity('settings');return;
      default:id satisfies never;
    }
  }
  async function showPalette(mode:PaletteMode){paletteMode=mode;paletteQuery='';paletteOpen=true;menuOpen='';await tick();paletteInput?.focus()}
  function paletteCommands(){const q=paletteQuery.toLowerCase();return commands.filter(item=>item.label.toLowerCase().includes(q))}
  function paletteFiles(){const q=paletteQuery.toLowerCase();return(project?.files??[]).filter(file=>file.path.toLowerCase().includes(q)).slice(0,30)}
  function runFirstPaletteItem(){if(paletteMode==='commands'){const command=paletteCommands().find(item=>commandEnabled(item.id));if(command)void executeCommand(command.id);return}const file=paletteFiles()[0];if(file){paletteOpen=false;void openFile(file.path)}}
  function startChord(value:string){pendingChord=value;window.clearTimeout(chordTimer);chordTimer=window.setTimeout(()=>pendingChord='',1500)}
  function keydown(event:KeyboardEvent){
    const mod=event.metaKey||event.ctrlKey,key=event.key.toLowerCase();
    if(event.key==='Escape'){pendingChord='';window.clearTimeout(chordTimer);paletteOpen=false;menuOpen='';editorActionsOpen=false;return}
    if(pendingChord){const chord=pendingChord;pendingChord='';window.clearTimeout(chordTimer);if(chord==='ctrl+k'&&mod&&key==='o'){event.preventDefault();void executeCommand('file.open');return}}
    if(mod&&!event.shiftKey&&key==='k'){event.preventDefault();startChord('ctrl+k');return}
    if(event.altKey&&!mod&&event.key==='ArrowLeft'){event.preventDefault();void executeCommand('nav.back');return}
    if(event.altKey&&!mod&&event.key==='ArrowRight'){event.preventDefault();void executeCommand('nav.forward');return}
    if(mod&&event.shiftKey&&key==='p'){event.preventDefault();void executeCommand('palette');return}
    if(mod&&!event.shiftKey&&!event.altKey&&key==='p'){event.preventDefault();void executeCommand('quickOpen');return}
    if(mod&&!event.shiftKey&&!event.altKey&&key==='n'){event.preventDefault();void executeCommand('file.new');return}
    if(mod&&!event.shiftKey&&!event.altKey&&key==='w'){event.preventDefault();void executeCommand('editor.close');return}
    if(mod&&!event.shiftKey&&!event.altKey&&key==='s'){event.preventDefault();void executeCommand('file.save');return}
    if(mod&&!event.shiftKey&&!event.altKey&&key==='b'){event.preventDefault();primaryOpen=!primaryOpen;return}
    if(mod&&!event.shiftKey&&!event.altKey&&key==='j'){event.preventDefault();void executeCommand('view.panel');return}
    if(mod&&event.shiftKey&&key==='e'){event.preventDefault();void executeCommand('view.explorer');return}
    if(mod&&event.shiftKey&&key==='f'){event.preventDefault();void executeCommand('view.search');return}
    if(mod&&event.shiftKey&&key==='g'){event.preventDefault();void executeCommand('view.source');return}
    if(mod&&!event.shiftKey&&!event.altKey&&event.key==='`'){event.preventDefault();void executeCommand('terminal.focus');return}
    if(event.key==='F2'){event.preventDefault();void executeCommand('file.rename');return}
    if(event.key==='F5'&&event.shiftKey){event.preventDefault();void executeCommand('emulator.stop');return}
    if(event.key==='F5'){event.preventDefault();void executeCommand('run');return}
    if(event.key==='F6'&&!event.shiftKey){event.preventDefault();void executeCommand('build')}
  }
</script>

<svelte:window onkeydown={keydown} onclick={dismissDropdowns}/>
<div class="workbench">
  <header class="titlebar">
    <div class="title-drag"><img class="app-logo" src="/exbasic-logo-icon.png" alt="exBASIC Studio" draggable="false"/></div>
    <nav class="menubar" aria-label="Application menu">{#each ['File','Edit','Selection','View','Go','Run','Terminal','Help'] as menu}<div class="menu-wrap"><button class:open={menuOpen===menu} onclick={()=>{editorActionsOpen=false;menuOpen=menuOpen===menu?'':menu}}>{menu}</button>{#if menuOpen===menu}<div class="menu-popup">{#each menuItems(menu) as item}<button disabled={!commandEnabled(item.action)} onclick={()=>executeCommand(item.action)}><span>{item.label}</span><kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}</div>{/each}</nav>
    <button class="nav-button" title="Navigate back" disabled={navigationIndex<=0} onclick={()=>navigate(-1)}><i class="codicon codicon-arrow-left"></i></button><button class="nav-button" title="Navigate forward" disabled={navigationIndex>=navigation.length-1} onclick={()=>navigate(1)}><i class="codicon codicon-arrow-right"></i></button>
    <button class="command-center" onclick={()=>showPalette('commands')}><i class="codicon codicon-search"></i><span>{project?.config.name??'exbasic-studio'}</span></button>
    <div class="title-actions"><button title="Toggle primary side bar" onclick={()=>primaryOpen=!primaryOpen}><i class="codicon codicon-layout-sidebar-left"></i></button><button title="Toggle panel" onclick={()=>panelOpen=!panelOpen}><i class="codicon codicon-layout-panel"></i></button><button title="Toggle secondary side bar" onclick={()=>secondaryOpen=!secondaryOpen}><i class="codicon codicon-layout-sidebar-right"></i></button></div>
    <div class="window-controls"><button aria-label="Minimize" onclick={()=>Window.Minimise()}><i class="codicon codicon-chrome-minimize"></i></button><button aria-label="Maximize" onclick={()=>Window.ToggleMaximise()}><i class="codicon codicon-chrome-maximize"></i></button><button class="close" aria-label="Close" onclick={()=>Window.Close()}><i class="codicon codicon-chrome-close"></i></button></div>
  </header>

  <div class="work-area">
    <aside class="activitybar"><div class="activity-top">{#each activities as item}<button class:active={primaryOpen&&activity===item.id} title={item.label} ondragenter={event=>switchActivityDuringDrag(event,item.id)} onclick={()=>switchActivity(item.id)}><i class={`codicon codicon-${item.icon}`}></i>{#if item.id==='source'&&git?.changes?.length}<span class="badge">{git.changes.length}</span>{/if}</button>{/each}</div><div class="activity-bottom"><button class:active={secondaryOpen} title="Claude Code account" onclick={()=>secondaryOpen=!secondaryOpen}><i class="codicon codicon-account"></i></button><button class:active={primaryOpen&&activity==='settings'} title="Manage" onclick={()=>switchActivity('settings')}><i class="codicon codicon-gear"></i></button></div></aside>

    {#if primaryOpen}<aside class="primary-sidebar">
      <div class="sidebar-title"><span>{activityTitle()}</span></div>
      {#if activity==='explorer'}
        {#if project}<div class="section-header"><i class="codicon codicon-chevron-down"></i><strong>{project.config.name.toUpperCase()}</strong><span class="section-actions project-actions"><button aria-label="New folder" title="New Folder" onclick={beginNewFolder}><i class="codicon codicon-new-folder"></i></button><button aria-label="New file" title="New File" onclick={beginNewFile}><i class="codicon codicon-new-file"></i></button><button aria-label="Refresh Explorer" title="Refresh Explorer" onclick={async()=>project=await studio.GetProject() as ProjectView}><i class="codicon codicon-refresh"></i></button></span></div>
          <div class="file-tree" role="tree" tabindex="0" id="project-drop-root" data-file-drop-target ondragover={event=>event.preventDefault()} ondrop={event=>dropOnProject(event,'')}>
            {#each projectTree() as entry}
              {#if entry.directory}
                <button id={`project-drop-${encodeURIComponent(entry.path)}`} data-file-drop-target draggable="true" ondragstart={event=>startProjectDrag(event,entry.path)} ondragover={event=>event.preventDefault()} ondrop={event=>dropOnProject(event,entry.path)} class:selected={selectedPath===entry.path} class="folder-row" style={`padding-left:${8+entry.depth*14}px`} onclick={()=>{selectedPath=entry.path;toggleFolder(entry.path)}} title={entry.path}><i class={`codicon codicon-chevron-${collapsedFolders.has(entry.path)?'right':'down'}`}></i><i class={`codicon codicon-folder${collapsedFolders.has(entry.path)?'':'-opened'}`}></i><span>{entry.name}</span></button>
              {:else}
                <button draggable="true" ondragstart={event=>startProjectDrag(event,entry.path)} ondragover={event=>event.preventDefault()} ondrop={event=>dropOnProject(event,entry.path.includes('/')?entry.path.slice(0,entry.path.lastIndexOf('/')):'')} class:active={activeFile===entry.path} class:selected={selectedPath===entry.path} style={`padding-left:${8+entry.depth*14}px`} onclick={()=>openFile(entry.path)} title={entry.path}><i class="codicon tree-spacer"></i><i class={`codicon codicon-${fileIcon(entry.path)}`}></i><span>{entry.name}</span>{#if tabs.find(tab=>tab.path===entry.path)?.dirty}<b>●</b>{/if}</button>
              {/if}
            {/each}
          </div>
          {#if newFilePath}<div class="new-file-row"><i class="codicon codicon-new-file"></i><input bind:this={newFileInput} aria-label="New file path" placeholder="src/new.bas" bind:value={newFilePath} onkeydown={event=>{if(event.key==='Enter')void makeFile();if(event.key==='Escape')newFilePath=''}}/><button title="Create file" onclick={makeFile}><i class="codicon codicon-check"></i></button></div>{/if}{#if newFolderPath}<div class="new-file-row"><i class="codicon codicon-new-folder"></i><input bind:this={newFolderInput} aria-label="New folder path" placeholder="src/new-folder" bind:value={newFolderPath} onkeydown={event=>{if(event.key==='Enter')void makeFolder();if(event.key==='Escape')newFolderPath=''}}/><button title="Create folder" onclick={makeFolder}><i class="codicon codicon-check"></i></button></div>{/if}{#if selectedPath}<div class="explorer-actions"><button title="Rename selected" onclick={renameSelected}><i class="codicon codicon-edit"></i> Rename</button><button title="Delete selected" onclick={deleteSelected}><i class="codicon codicon-trash"></i> Delete</button></div>{/if}<div class="collapsed-section"><i class="codicon codicon-chevron-right"></i> OUTLINE</div><div class="collapsed-section"><i class="codicon codicon-chevron-right"></i> TIMELINE</div>
        {:else}<div class="welcome-card"><p>You have not yet opened a folder.</p><label for="folder-path">Folder path</label><div class="path-picker"><input id="folder-path" bind:value={projectPath} onkeydown={event=>{if(event.key==='Enter')void openProject()}}/><button title="Browse folders" onclick={chooseProject}><i class="codicon codicon-folder-opened"></i></button></div><button class="accent" onclick={chooseProject}>Open Folder…</button><button class="remote-open" disabled={!env?.sshAvailable} onclick={showRemoteDialog}><i class="codicon codicon-remote"></i> Open Remote Project over SSH</button><div class="divider"><span>or create a project</span></div><label for="project-name">Project name</label><input id="project-name" bind:value={projectName}/><button onclick={createProject}>Create Project</button></div>{/if}
      {:else if activity==='atr'}
        {#if atr}
          <div class="section-header"><i class="codicon codicon-database"></i><strong>{fileName(atr.path).toUpperCase()}</strong><span class="section-actions"><button title="Add files or folders" onclick={chooseATRImports}><i class="codicon codicon-add"></i></button><button title="New ATR folder" onclick={()=>atrNewFolder='NEWFOLDER'}><i class="codicon codicon-new-folder"></i></button><button title="Refresh" onclick={refreshATR}><i class="codicon codicon-refresh"></i></button><button title="Open another ATR" onclick={chooseATR}><i class="codicon codicon-folder-opened"></i></button></span></div>
          <div class="atr-summary"><span>{atr.filesystem==='eos'?'EOSFS':'SDFS'}</span><span>{atr.sectors} × {atr.sectorSize}</span><span>{formatBytes(atr.freeBytes)} free</span></div>
          <div class="atr-tree" role="tree" tabindex="0" id="atr-drop-root" data-file-drop-target ondragover={event=>event.preventDefault()} ondrop={event=>dropOnATR(event,'')}>
            {#if atr.entries.length===0}<div class="atr-drop-hint"><i class="codicon codicon-cloud-upload"></i> Drop files here</div>{/if}
            {#each visibleATREntries() as entry}
              <button id={entry.directory?`atr-drop-${encodeURIComponent(entry.path)}`:undefined} data-file-drop-target={entry.directory?'':undefined} draggable="true" ondragstart={event=>startATRDrag(event,entry.path)} ondragover={event=>{if(entry.directory)event.preventDefault()}} ondrop={event=>{if(entry.directory)void dropOnATR(event,entry.path)}} class:selected={atrSelected===entry.path} class:folder-row={entry.directory} style={`padding-left:${8+atrDepth(entry.path)*14}px`} onclick={()=>{atrSelected=entry.path;if(entry.directory)toggleATRFolder(entry.path)}} title={`${entry.path} · ${formatBytes(entry.size)}`}>
                {#if entry.directory}<i class={`codicon codicon-chevron-${atrCollapsed.has(entry.path)?'right':'down'}`}></i><i class={`codicon codicon-folder${atrCollapsed.has(entry.path)?'':'-opened'}`}></i>{:else}<i class={`codicon codicon-${fileIcon(entry.path)}`}></i>{/if}<span>{entry.name}</span>{#if entry.boot}<i class="codicon codicon-debug-start atr-boot" title="Boot file"></i>{/if}<small>{entry.directory?'':formatBytes(entry.size)}</small>
              </button>
            {/each}
          </div>
          {#if atrNewFolder}<div class="new-file-row"><i class="codicon codicon-new-folder"></i><input aria-label="New ATR folder" bind:value={atrNewFolder} onkeydown={event=>{if(event.key==='Enter')void makeATRFolder();if(event.key==='Escape')atrNewFolder=''}}/><button title="Create folder" onclick={makeATRFolder}><i class="codicon codicon-check"></i></button></div>{/if}
          <div class="atr-drop-help"><i class="codicon codicon-info"></i> Drag project or desktop files in. Drag ATR entries into the project explorer to extract.</div>
          {#if atrSelected}<div class="explorer-actions atr-actions"><button title="Extract selected" onclick={extractATRSelected}><i class="codicon codicon-export"></i> Extract</button><button title="Rename selected" onclick={renameATRSelected}><i class="codicon codicon-edit"></i> Rename</button><button title="Delete selected" onclick={removeATRSelected}><i class="codicon codicon-trash"></i> Delete</button></div>{/if}
        {:else}<div class="welcome-card atr-welcome"><p>Open an SDFS or EOSFS ATR image and manage it like a project folder.</p><button class="accent" onclick={chooseATR}><i class="codicon codicon-folder-opened"></i> Open ATR Image</button>{#if project&&project.kind==='local'}<button onclick={openConfiguredATR}><i class="codicon codicon-disc"></i> Open Project ATR</button>{/if}<p>Files and folders can be dragged between your desktop, project explorer, and the ATR tree.</p></div>{/if}
      {:else if activity==='search'}<div class="sidebar-form"><div class="search-box"><input aria-label="Search project" placeholder="Search" bind:value={searchQuery} onkeydown={e=>{if(e.key==='Enter')void searchProject()}}/><button title="Search" onclick={searchProject}><i class="codicon codicon-search"></i></button></div><small>{searchResults.length} results</small></div><div class="search-results">{#each searchResults as result}<button onclick={()=>openSearchResult(result)}><strong>{result.path}<span>:{result.line}</span></strong><small>{result.text}</small></button>{/each}</div>
      {:else if activity==='source'}
        {#if project}
          <div class="scm-compose"><textarea aria-label="Commit message" rows="3" placeholder="Message (Ctrl+Enter to commit)" bind:value={commitMessage} onkeydown={e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&commitMessage.trim())void gitAction('commit')}}></textarea><button class="accent" disabled={!commitMessage.trim()||!git?.available} onclick={()=>gitAction('commit')}>Commit</button></div>
          <div class="scm-toolbar"><button title="Refresh source control" onclick={refreshGit}><i class="codicon codicon-refresh"></i></button>{#if git?.changes?.length}<button title="Stage all changes" onclick={()=>gitAction('stageAll')}><i class="codicon codicon-add"></i> All</button><button title="Unstage all changes" onclick={()=>gitAction('unstageAll')}><i class="codicon codicon-remove"></i> All</button>{/if}</div>
          <div class="scm-state">
            {#if !git?.available}<div class="empty-state">No Git repository was found.</div><button class="accent wide" onclick={()=>gitAction('init')}>Initialize Repository</button>
            {:else}<div class="section-header"><i class="codicon codicon-chevron-down"></i><strong>CHANGES</strong><span>{git?.changes?.length??0}</span></div>{#if !git?.changes?.length}<div class="empty-state">There are no pending changes.</div>{/if}
              {#each (git?.changes ?? []) as change}<div class="scm-change"><button class="change-file" title={`View diff for ${change.path}`} onclick={()=>gitAction('diff',change.path)}><i class={`codicon codicon-${fileIcon(change.path)}`}></i><span>{change.path}</span><b>{change.index==='?'?'U':change.index.trim()}{change.worktree.trim()}</b></button>{#if change.index!==' '&&change.index!=='?'}<button title="Unstage" onclick={()=>gitAction('unstage',change.path)}><i class="codicon codicon-remove"></i></button>{:else}<button title="Stage" onclick={()=>gitAction('stage',change.path)}><i class="codicon codicon-add"></i></button>{/if}</div>{/each}
            {/if}
            {#if diff}<div class="diff-title">Diff: {diffPath}<button title="Close diff" onclick={()=>{diff=''}}><i class="codicon codicon-close"></i></button></div><pre class="diff">{diff}</pre>{/if}
          </div>
        {:else}<div class="empty-state">Open a folder to use source control.</div>{/if}
      {:else if activity==='run'}<div class="run-actions"><button class="run-main" disabled={!project||busy} onclick={()=>compile(true)}><i class="codicon codicon-play"></i><span>Run exBASIC Project</span></button><button disabled={!project||busy} onclick={()=>compile(false)}><i class="codicon codicon-tools"></i><span>Build Project{project?.config.atr.enabled?' + ATR':''}</span></button><button onclick={openInteractiveEmulator}><i class="codicon codicon-device-desktop"></i><span>Open Atari800 Screen</span></button></div><div class="collapsed-section"><i class="codicon codicon-chevron-right"></i> EMULATOR</div><div class="empty-state">Atari800 runs inside an editor tab. Select a reusable profile, mount media, and start or restart the machine without opening another window.</div>
      {:else if activity==='emulator'}
        <div class="emulator-sidebar-status"><i class:running={emulatorRunning} class="codicon codicon-circle-filled"></i><strong>{emulatorRunning?'Running':'Stopped'}</strong><span>{emulatorOpen?'Tab open':'Tab closed'}</span></div>
        <div class="sidebar-form"><label for="sidebar-emulator-profile">Profile</label><select id="sidebar-emulator-profile" value={emulatorProfileId} onchange={event=>selectEmulatorProfile((event.currentTarget as HTMLSelectElement).value)}>{#each emulatorProfiles as profile}<option value={profile.id}>{profile.name}</option>{/each}</select></div>
        <div class="run-actions"><button class="run-main" onclick={openInteractiveEmulator}><i class="codicon codicon-device-desktop"></i><span>{emulatorOpen?'Show Atari800 Screen':'Open Atari800 Screen'}</span></button><button disabled={!emulatorOpen||busy} onclick={closeEmulator}><i class="codicon codicon-close"></i><span>Close Atari800 Tab</span></button><button disabled={emulatorRunning||busy} onclick={startEmulator}><i class="codicon codicon-play"></i><span>Start Emulator</span></button><button disabled={!emulatorRunning||busy} onclick={restartEmulator}><i class="codicon codicon-debug-restart"></i><span>Restart Emulator</span></button><button disabled={!emulatorRunning||busy} onclick={stopEmulator}><i class="codicon codicon-debug-stop"></i><span>Stop Emulator</span></button></div>
        <div class="empty-state">Open shows the emulator as an editor tab beside your source code. Closing the tab also stops the emulated machine.</div>
      {:else if activity==='extensions'}<div class="sidebar-form"><div class="search-box"><input aria-label="Search extensions" placeholder="Filter installed extensions" bind:value={extensionQuery}/><button title="Refresh extensions" onclick={showExtensions}><i class="codicon codicon-refresh"></i></button></div></div><div class="extension-list">{#if extensions.length===0}<div class="empty-state">No installed extensions found. Drop manifests in the configured extensions directory to have them discovered.</div>{/if}{#if extensions.length>0&&filteredExtensions().length===0}<div class="empty-state">No installed extensions match this filter.</div>{/if}{#each filteredExtensions() as ext}<div class="extension-item"><span class="extension-icon"><i class="codicon codicon-extensions"></i></span><div><strong>{ext.name}</strong><small>{ext.id} · {ext.version}</small><em>{ext.status}</em></div></div>{/each}</div>
      {:else if activity==='manual'}<div class="sidebar-form"><div class="search-box"><input aria-label="Search manual" placeholder="Search manual" bind:value={manualSearch} onkeydown={e=>{if(e.key==='Enter')void searchDocs()}}/><button title="Search manual" onclick={searchDocs}><i class="codicon codicon-search"></i></button></div><select aria-label="Manual chapter" bind:value={chosenChapter} onchange={()=>{if(chosenChapter)void readChapter(chosenChapter)}}><option value="">Choose a chapter</option>{#each chapters as chapter}<option value={chapter}>{chapter}</option>{/each}</select></div><div class="manual-results">{#each hits as hit}<button onclick={()=>readChapter(hit.file)}><strong>{hit.title}</strong><small>{hit.snippet}</small></button>{/each}{#if chapterText}<pre>{chapterText}</pre>{/if}</div>
      {:else if activity==='settings'}
        <div class="settings-pane"><h3>Project Settings</h3>{#if draft}
          <label for="compiler-setting">exBASIC executable</label><input id="compiler-setting" bind:value={draft.compiler}/>
          <label for="emulator-setting">Atari800 headless bridge</label><input id="emulator-setting" bind:value={draft.emulator}/><p class="setting-help">The bundled bridge renders the official libatari800 framebuffer inside an editor tab; it never opens a separate emulator window.</p>
          <label for="entry-setting">Entry source</label><input id="entry-setting" bind:value={draft.entry}/>
          <label for="output-setting">Output file</label><input id="output-setting" bind:value={draft.output}/>
          <label for="target-setting">Target</label><select id="target-setting" bind:value={draft.target}><option value="atari">Atari .XEX</option><option value="atari-cart">8 KB Cartridge .ROM</option></select>
          <label for="native-setting">Native mode</label><select id="native-setting" bind:value={draft.native}><option value="auto">Auto</option><option value="hot">Hot paths</option><option value="all">Native all</option><option value="none">Bytecode only</option></select>
          <label class="check"><input type="checkbox" bind:checked={draft.debug}/> Debug symbols</label>
          <h3>ATR Disk Image</h3><label class="check"><input type="checkbox" bind:checked={draft.atr.enabled}/> Package builds into an ATR image</label>
          {#if draft.atr.enabled}
            <label for="atr-filesystem-setting">Filesystem</label>
            <select id="atr-filesystem-setting" bind:value={draft.atr.filesystem} onchange={()=>{if(draft?.atr.filesystem==='eos')draft.atr.boot=false}}><option value="sparta">SpartaDOS / BW-DOS (SDFS)</option><option value="eos">ExtendedOS (EOSFS)</option></select>
            <label for="atr-output-setting">ATR output file</label><input id="atr-output-setting" bind:value={draft.atr.output}/>
            <label for="atr-tool-setting">mkatr-go executable</label><input id="atr-tool-setting" bind:value={draft.atr.tool}/>
            <label class="check"><input type="checkbox" bind:checked={draft.atr.boot} disabled={draft.atr.filesystem==='eos'}/> Boot compiled application</label>
            {#if draft.atr.filesystem==='eos'}<p class="setting-help">EOSFS uses extent lists. Mount this image under ExtendedOS; the SDFS bootloader cannot boot an EOSFS file.</p>{/if}
            <label class="check"><input type="checkbox" bind:checked={draft.atr.exactSize}/> Use exact sector count</label>
            <label for="atr-size-setting">Minimum image size in bytes (0 = automatic)</label><input id="atr-size-setting" type="number" min="0" max="16776576" bind:value={draft.atr.minimumSize}/>
            <label for="atr-page-setting">Bootloader page (4–239)</label><input id="atr-page-setting" type="number" min="4" max="239" bind:value={draft.atr.bootPage}/>
            <label for="atr-files-setting">Additional project files (comma-separated)</label><input id="atr-files-setting" value={draft.atr.files.join(', ')} oninput={event=>draft!.atr.files=(event.currentTarget as HTMLInputElement).value.split(',').map(value=>value.trim()).filter(Boolean)}/>
            <p class="setting-help">The compiled XEX is always copied into the image. Additional files are copied to the ATR root.</p>
          {/if}
          <button class="accent wide" onclick={saveSettings}>Save Settings</button>
        {:else}<div class="empty-state">Open a project to configure its toolchain.</div>{/if}</div>{/if}
    </aside>{/if}

    <main class="editor-group">
      <div class="editor-tabs">{#if welcomeOpen&&tabs.length===0}<div role="button" tabindex="0" class:active={activeFile!=='@atari800'} class="editor-tab welcome" onclick={switchToWelcome} onkeydown={event=>{if(event.key==='Enter')switchToWelcome()}}><i class="codicon codicon-symbol-method"></i><span>Welcome.bas</span><button class="codicon codicon-close close-tab" title="Close Welcome" onclick={closeWelcome}></button></div>{/if}{#if !emulatorOpen}<button class="editor-tab emulator-launch" title="Open the Atari800 screen (stopped)" onclick={openInteractiveEmulator}><i class="codicon codicon-device-desktop"></i><span>Open Atari800</span></button>{/if}{#each tabs as tab}<div role="button" tabindex="0" class:active={activeFile===tab.path} class="editor-tab" onclick={()=>switchTab(tab.path)} onkeydown={event=>{if(event.key==='Enter')switchTab(tab.path)}}><i class={`codicon codicon-${fileIcon(tab.path)}`}></i><span>{fileName(tab.path)}</span>{#if tab.dirty}<b>●</b>{/if}<button class="codicon codicon-close close-tab" title={`Close ${fileName(tab.path)}`} onclick={event=>closeTab(tab.path,event)}></button></div>{/each}{#if emulatorOpen}<div role="button" tabindex="0" class:active={activeFile==='@atari800'} class="editor-tab emulator-tab" onclick={switchToEmulator} onkeydown={event=>{if(event.key==='Enter')switchToEmulator()}}><i class="codicon codicon-device-desktop"></i><span>Atari800 Screen</span><b class="frame-indicator">{emulatorFrame}</b><button class="codicon codicon-close close-tab" title="Stop and close Atari800" onclick={closeEmulator}></button></div>{/if}<span class="tab-spacer"></span><button class:active={splitOpen} class="editor-action" title="Toggle editor split" onclick={toggleSplit} disabled={!commandEnabled('editor.split')}><i class="codicon codicon-split-horizontal"></i></button><div class="editor-more"><button class:active={editorActionsOpen} class="editor-action" title="More editor actions" onclick={()=>{menuOpen='';editorActionsOpen=!editorActionsOpen}}><i class="codicon codicon-ellipsis"></i></button>{#if editorActionsOpen}<div class="editor-menu"><button disabled={!commandEnabled('file.save')} onclick={()=>executeCommand('file.save')}><span>Save</span><kbd>Ctrl+S</kbd></button><button disabled={!commandEnabled('editor.copyPath')} onclick={()=>executeCommand('editor.copyPath')}><span>Copy Path</span></button><button disabled={!commandEnabled('editor.split')} onclick={()=>executeCommand('editor.split')}><span>{splitOpen?'Close Split':'Split Editor'}</span></button><button disabled={!commandEnabled('editor.close')} onclick={()=>executeCommand('editor.close')}><span>Close Editor</span><kbd>Ctrl+W</kbd></button></div>{/if}</div></div>
      <div class="breadcrumbs">{#if activeFile==='@atari800'}<i class="codicon codicon-device-desktop"></i><span>Atari800</span><i class="codicon codicon-chevron-right"></i><span>Rendered Screen</span>{:else if activeFile}<i class="codicon codicon-folder"></i>{#each activeFile.split('/') as part,index}<span>{part}</span>{#if index<activeFile.split('/').length-1}<i class="codicon codicon-chevron-right"></i>{/if}{/each}{:else}<span>exbasic-studio</span>{/if}</div>
      <div class:split={splitOpen&&activeFile!=='@atari800'} class="editor-views"><div class:hidden-view={activeFile==='@atari800'} class="editor-container" bind:this={editorHost}></div>{#if splitOpen&&activeFile!=='@atari800'}<div class="editor-container split-preview"><div class="split-label"><i class="codicon codicon-preview"></i> Read-only preview</div><div class="split-host" bind:this={splitHost}></div></div>{/if}{#if activeFile==='@atari800'}<!-- svelte-ignore a11y_no_noninteractive_tabindex a11y_no_noninteractive_element_interactions --><div class="emulator-view" tabindex="0" role="application" aria-label="Atari800 rendered screen" onkeydown={event=>emulatorKey(event,true)} onkeyup={event=>emulatorKey(event,false)} onblur={releaseEmulatorKeys}>
        <div class="emulator-toolbar"><div class="emulator-status-group"><span class:running={emulatorRunning} class="emulator-state" title={emulatorRunning?`Atari800 is running at frame ${emulatorFrame}`:'Atari800 is stopped'}><i class="codicon codicon-circle-filled"></i> {emulatorRunning?`Running · ${emulatorFrame}`:'Stopped'}</span>{#if emulatorHostDevice}<span class="emulator-state running" title="Project H folder is mapped read/write and synchronized when Atari800 stops"><i class="codicon codicon-folder-opened"></i> {emulatorHostDeviceName} project H</span>{/if}</div><select aria-label="Atari800 profile" value={emulatorProfileId} onchange={event=>selectEmulatorProfile((event.currentTarget as HTMLSelectElement).value)}>{#each emulatorProfiles as profile}<option value={profile.id}>{profile.name}</option>{/each}</select><div class="emulator-actions"><button class="primary-control" aria-label="Start Atari800" title="Start Atari800" disabled={emulatorRunning||busy} onclick={startEmulator}><i class="codicon codicon-play"></i></button><button aria-label="Restart Atari800" title="Restart Atari800" disabled={busy} onclick={restartEmulator}><i class="codicon codicon-debug-restart"></i></button><button aria-label="Stop Atari800" title="Stop Atari800" disabled={!emulatorRunning||busy} onclick={stopEmulator}><i class="codicon codicon-debug-stop"></i></button><button aria-label="Capture Atari800 screen" title="Save current frame as PNG" disabled={!emulatorImage} onclick={captureEmulator}><i class="codicon codicon-camera"></i></button><button class:active={emulatorConfigOpen} aria-label="Configure Atari800" title="Configure emulator" onclick={()=>emulatorConfigOpen=!emulatorConfigOpen}><i class="codicon codicon-settings-gear"></i></button></div></div>
        <div class="emulator-workspace"><div class="emulator-stage"><div class="atari-display">{#if emulatorImage}<img src={emulatorImage} style={`width:min(100%, ${336*(emulatorDraft?.scale??2)}px)`} alt={`Atari800 frame ${emulatorFrame}`} draggable="false"/>{:else if emulatorRunning}<div class="emulator-loading"><i class="codicon codicon-loading codicon-modifier-spin"></i> Starting Atari800…</div>{:else}<div class="emulator-empty"><i class="codicon codicon-device-desktop"></i><strong>Atari800 is stopped</strong><span>Choose a profile and press Start. A project is not required.</span><button class="accent" onclick={startEmulator}><i class="codicon codicon-play"></i> Start Emulator</button></div>{/if}</div><small>Click the screen to focus it. Keyboard input is sent directly to the emulated Atari.</small></div>
          {#if emulatorConfigOpen&&emulatorDraft}<aside class="emulator-config">
            <header><strong>Emulator Profile</strong><button title="New profile" onclick={newEmulatorProfile}><i class="codicon codicon-add"></i></button></header>
            <label for="emu-profile-name">Name</label><input id="emu-profile-name" bind:value={emulatorDraft.name}/>
            <h4>System</h4>
            <div class="emulator-field-row"><div><label for="emu-machine">Machine</label><select id="emu-machine" bind:value={emulatorDraft.machine}><option value="atari">Atari 400/800</option><option value="xl">Atari XL</option><option value="xe">Atari XE</option><option value="5200">Atari 5200</option></select></div><div><label for="emu-video">Video</label><select id="emu-video" bind:value={emulatorDraft.video}><option value="ntsc">NTSC</option><option value="pal">PAL</option></select></div></div>
            <div class="emulator-field-row"><div><label for="emu-memory">Memory</label><select id="emu-memory" bind:value={emulatorDraft.memory} disabled={emulatorDraft.machine==='5200'||emulatorDraft.ultimate1MB}><option value="64">64K</option><option value="128">128K</option><option value="256">256K Rambo</option><option value="320-rambo">320K Rambo</option><option value="320-compy">320K Compy Shop</option><option value="1088">1088K</option></select></div><div><label for="emu-cpu-speed">CPU speed</label><select id="emu-cpu-speed" bind:value={emulatorDraft.cpuSpeed}><option value={100}>1×</option><option value={150}>1.5×</option><option value={200}>2×</option><option value={300}>3×</option><option value={500}>5×</option></select></div></div>
            <label class="check"><input type="checkbox" bind:checked={emulatorDraft.ultimate1MB}/> Ultimate 1MB memory banking</label>
            <label class="check"><input type="checkbox" bind:checked={emulatorDraft.basic}/> Enable Atari BASIC</label>
            <label class="check"><input type="checkbox" bind:checked={emulatorDraft.sioPatch}/> Enable fast SIO patch</label>
            <label class="check"><input type="checkbox" bind:checked={emulatorDraft.eos}/> Mount bundled EOS cartridge</label>
            <h4>Floppy drives</h4>
            {#each emulatorDraft.drives as drive,index}
              <div class="emulator-device"><div class="emulator-device-title"><label class="check"><input type="checkbox" bind:checked={drive.enabled}/> D{index+1}:</label><label class="check"><input type="checkbox" bind:checked={drive.readOnly}/> Read only</label></div><div class="emulator-media"><input bind:value={drive.image} placeholder="ATR, XFD, or ATX image"/><button title={`Browse D${index+1}: image`} onclick={()=>chooseEmulatorDrive(index)}><i class="codicon codicon-folder-opened"></i></button></div></div>
            {/each}
            <h4>R: serial device</h4>
            <label for="emu-r-mode">Interface</label><select id="emu-r-mode" bind:value={emulatorDraft.rDevice.mode} onchange={()=>{if(emulatorDraft?.rDevice.mode==='rverter')emulatorDraft.rDevice.modem=true}}><option value="disabled">Disabled</option><option value="850">Atari 850</option><option value="rverter">R-Verter modem</option></select>
            {#if emulatorDraft.rDevice.mode!=='disabled'}<div class="emulator-field-row"><div><label for="emu-r-port">R1: TCP port</label><input id="emu-r-port" type="number" min="1" max="65532" bind:value={emulatorDraft.rDevice.listenPort}/></div><div><label for="emu-r-baud">Line speed</label><select id="emu-r-baud" bind:value={emulatorDraft.rDevice.connectBaud}><option value={300}>300 baud</option><option value={1200}>1200 baud</option><option value={2400}>2400 baud</option><option value={4800}>4800 baud</option><option value={9600}>9600 baud</option><option value={19200}>19.2K baud</option></select></div></div><label class="check"><input type="checkbox" bind:checked={emulatorDraft.rDevice.modem} disabled={emulatorDraft.rDevice.mode==='rverter'}/> Hayes-compatible TCP modem{emulatorDraft.rDevice.mode==='rverter'?' (required by R-Verter)':''}</label><p>Bidirectional: dial out with ATDI host port, or accept BBS callers on R1: at this port. R2:–R4: use the next three ports.</p><label for="emu-r-serial">Host serial port <small>(Linux only; blank uses TCP)</small></label><input id="emu-r-serial" bind:value={emulatorDraft.rDevice.serialPort} placeholder="/dev/ttyUSB0"/>{/if}
            <h4>IDE Plus 2.0</h4>
            <label class="check"><input type="checkbox" bind:checked={emulatorDraft.ide.enabled}/> Enable D500–D50F IDE interface</label>
            {#if emulatorDraft.ide.enabled}<div class="emulator-media"><input bind:value={emulatorDraft.ide.image} placeholder="Raw hard disk image"/><button title="Browse IDE image" onclick={chooseIDEImage}><i class="codicon codicon-folder-opened"></i></button></div><label class="check"><input type="checkbox" bind:checked={emulatorDraft.ide.compactFlash}/> CompactFlash identify mode</label>{/if}
            <h4>Startup</h4>
            <label for="emu-scale">Display scale</label><select id="emu-scale" bind:value={emulatorDraft.scale}><option value={1}>1×</option><option value={2}>2×</option><option value={3}>3×</option><option value={4}>4×</option></select>
            <label for="emu-media">Startup media</label><div class="emulator-media"><input id="emu-media" bind:value={emulatorDraft.media} placeholder="XEX, CAR, ROM, or fallback D1: ATR"/><button title="Browse media" onclick={chooseEmulatorMedia}><i class="codicon codicon-folder-opened"></i></button></div>
            <label for="emu-arguments">Advanced Atari800 arguments</label><input id="emu-arguments" bind:value={emulatorArgs} placeholder="One argument per comma"/><p>Advanced values are passed directly to the bundled Atari800 core, one argument per comma.</p>
            <footer><button disabled={!emulatorDraft.id||emulatorProfiles.length<=1} onclick={deleteEmulatorProfile}><i class="codicon codicon-trash"></i> Delete</button><button class="accent" onclick={saveEmulatorProfile}><i class="codicon codicon-save"></i> Save Profile</button></footer>
          </aside>{/if}</div>
      </div>{/if}</div>
      {#if panelOpen}<section class:maximized={panelMaximized} class="panel"><div class="panel-tabs"><div class="panel-tab-list">{#each ['problems','output','terminal'] as item}<button class:active={panelTab===item} onclick={()=>panelTab=item as PanelTab}>{item.toUpperCase()}{#if item==='problems'&&problems.length}<span>{problems.length}</span>{/if}</button>{/each}</div><div class="panel-actions"><button title={panelMaximized?'Restore panel':'Maximize panel'} onclick={()=>panelMaximized=!panelMaximized}><i class={`codicon codicon-chevron-${panelMaximized?'down':'up'}`}></i></button><button title="Close panel" onclick={()=>panelOpen=false}><i class="codicon codicon-close"></i></button></div></div><div class="panel-content">{#if panelTab==='terminal'}<div class="terminal"><pre>{terminalLog}</pre><div class="terminal-prompt"><span>PS {terminalCwd||project?.root||'>'}&gt;</span><input bind:this={terminalInput} bind:value={terminalCommand} disabled={!project} aria-busy={busy} onkeydown={terminalKeydown} autocomplete="off" spellcheck="false"/></div></div>{:else if panelTab==='output'}<pre class="output-view">{output}</pre>{:else}<div class="problems-view">{#if problems.length===0}<div class="empty-panel">No problems have been detected in the workspace.</div>{/if}{#each problems as problem}<div><i class="codicon codicon-error"></i><pre>{problem}</pre></div>{/each}</div>{/if}</div></section>{/if}
    </main>

    {#if secondaryOpen}<aside class="secondary-sidebar"><div class="secondary-tabs"><button class="active"><i class="codicon codicon-sparkle"></i> Claude Code</button><span></span><button title="New conversation" disabled={!project||busy} onclick={resetClaude}><i class="codicon codicon-add"></i></button><button title="Close" onclick={()=>secondaryOpen=false}><i class="codicon codicon-close"></i></button></div><div class="claude-toolbar"><button title="Start new Claude conversation" disabled={!project||busy} onclick={resetClaude}><i class="codicon codicon-arrow-left"></i></button><span>{project?'Project conversation':'No project open'}</span><i class:offline={!env?.claudeAvailable} class="codicon codicon-circle-filled claude-status" title={env?.claudeVersion||'Claude Code unavailable'}></i></div><div class="chat-scroll">{#if chat.length===0}<div class="claude-welcome"><span class="claude-logo">A</span><h2>Claude Code</h2><p>{env?.claudeAvailable?`Connected to ${env.claudeVersion}`:'Claude Code was not found.'}</p><p>Plan inspects the workspace. Edit may change files. Auto can use the local Claude Code toolchain autonomously under its configured permissions.</p></div>{/if}{#each chat as message}<div class:assistant={message.role==='assistant'} class:user={message.role==='user'} class="chat-message"><div class="message-role">{message.role==='assistant'?'Claude':'You'}</div><pre>{message.text}</pre></div>{/each}{#if busy&&status.startsWith('Claude')}<div class="claude-thinking"><i class="codicon codicon-loading codicon-modifier-spin"></i> Working…</div>{/if}</div><div class="chat-composer"><textarea rows="4" aria-label="Ask Claude Code" placeholder="Ask Claude Code (Ctrl+Enter to send)" bind:value={prompt} disabled={!project||!env?.claudeAvailable||busy} onkeydown={e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter')void askClaude()}}></textarea><div class="composer-actions"><button class:active={includeSelection} title={includeSelection?'Selected editor text will be attached':'Selected editor text will not be attached'} onclick={()=>includeSelection=!includeSelection}><i class="codicon codicon-attach"></i></button><select aria-label="Claude permission mode" bind:value={claudeMode} disabled={busy}><option value="plan">Plan</option><option value="edit">Edit</option><option value="auto">Auto</option></select><button class="send" title="Send to Claude Code" disabled={!prompt.trim()||!project||!env?.claudeAvailable||busy} onclick={askClaude}><i class="codicon codicon-send"></i></button></div></div></aside>{/if}
  </div>

  <footer class="statusbar"><div class="status-left"><button class="remote" title="Open an SSH remote" onclick={showRemoteDialog}><i class="codicon codicon-remote"></i>{#if project?.kind==='ssh'} SSH: {project.remoteHost}{/if}</button><button onclick={()=>showActivity('source')}><i class="codicon codicon-source-control"></i> {git?.branch||'--'}</button><button onclick={()=>{panelOpen=true;panelTab='problems'}}><i class="codicon codicon-error"></i> {problems.length}</button><span><i class="codicon codicon-warning"></i> 0</span></div><div class="status-message">{#if busy}<i class="codicon codicon-sync codicon-modifier-spin"></i>{/if} {status}</div><div class="status-right"><span>Ln {cursorLine}, Col {cursorColumn}</span><span>Spaces: 2</span><span>UTF-8</span><span>{editorText().includes('\r\n')?'CRLF':'LF'}</span><span>{project?.config.target||'Atari 8-bit'}</span><button onclick={()=>secondaryOpen=!secondaryOpen}><i class="codicon codicon-sparkle"></i> Claude Code</button></div></footer>

  {#if paletteOpen}<div class="palette-backdrop"><div class="palette"><div class="palette-input"><span>{paletteMode==='commands'?'>':' '}</span><input bind:this={paletteInput} bind:value={paletteQuery} placeholder={paletteMode==='commands'?'Type the name of a command':'Search files by name'} onkeydown={e=>{if(e.key==='Enter')runFirstPaletteItem()}}/></div><div class="palette-results">{#if paletteMode==='commands'}{#each paletteCommands() as command}<button disabled={!commandEnabled(command.id)} onclick={()=>executeCommand(command.id)}><i class={`codicon codicon-${command.icon??'symbol-event'}`}></i><span>{command.label}</span><kbd>{command.shortcut??''}</kbd></button>{/each}{:else}{#each paletteFiles() as file}<button onclick={()=>{paletteOpen=false;void openFile(file.path)}}><i class={`codicon codicon-${fileIcon(file.path)}`}></i><span>{file.path}</span></button>{/each}{/if}</div></div></div>{/if}
  {#if remoteDialog}<div class="modal-backdrop" role="presentation" onclick={event=>{if(event.target===event.currentTarget)remoteDialog=false}}><div class="remote-dialog" role="dialog" aria-modal="true" aria-labelledby="remote-title"><header><h2 id="remote-title"><i class="codicon codicon-remote"></i> Connect to SSH Host</h2><button title="Close" onclick={()=>remoteDialog=false}><i class="codicon codicon-close"></i></button></header><p>Uses your installed OpenSSH client and its system defaults, agent, keys, known_hosts, Include, Match, and ProxyJump configuration.</p><label for="ssh-host">SSH host or config alias</label><input id="ssh-host" list="ssh-hosts" bind:value={sshHost} placeholder="buildbox"/><datalist id="ssh-hosts">{#each sshHosts as host}<option value={host.alias}></option>{/each}</datalist><label for="ssh-path">Remote project path</label><input id="ssh-path" bind:value={sshPath} placeholder="~/project or /srv/project"/><label for="ssh-config">Config file override <small>(blank uses system default)</small></label><div class="remote-config-row"><input id="ssh-config" bind:value={sshConfigFile} placeholder="~/.ssh/config"/><button onclick={showRemoteDialog} title="Reload hosts"><i class="codicon codicon-refresh"></i></button></div>{#if resolvedSSH}<div class="resolved-ssh"><strong>{resolvedSSH.user}@{resolvedSSH.hostName}:{resolvedSSH.port}</strong><span>Host checking: {resolvedSSH.strictHostKeyChecking}</span>{#if resolvedSSH.proxyJump&&resolvedSSH.proxyJump!=='none'}<span>Jump host: {resolvedSSH.proxyJump}</span>{/if}<span>{resolvedSSH.identityFiles.length} configured identities</span></div>{/if}<footer><button onclick={inspectRemote} disabled={!sshHost.trim()||busy}>Inspect Configuration</button><button class="accent" onclick={connectRemote} disabled={!sshHost.trim()||!sshPath.trim()||busy}>Connect</button></footer></div></div>{/if}
</div>
